mapper.select:
SELECT e.event_log_id::TEXT AS row_id, e.event_type, c.code_nm AS event_type_nm, e.user_id, e.target_table, e.target_id, e.device_type, e.user_agent, e.reg_dt, e.reg_ip FROM t_event_log e LEFT JOIN t_code c ON c.code_id = e.event_type AND c.p_code_id = 'EVENT00'
AND e.event_type = #{eventType}
ORDER BY e.event_log_id DESC LIMIT #{size} OFFSET #{offset}
